"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[27166],{85064:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"EnemyBrain","desc":"Centralized enemy AI director. Ticks every armed enemy at TICK_HZ through two\\nindependent concerns: MOVEMENT (pathfind toward the nearest player to a comfort\\ndistance) and FIRING (burst/cooldown, run-and-gun). Humanoid bodies walk with\\n`Humanoid:MoveTo`. Bodies with no Humanoid (attribute health, anchored root,\\ne.g. pirate boarders) are moved by CFrame, snapped to the floor (PirateMove),\\nalways face their target, and strafe side to side while they hold range.\\nArmed bodies bend at the waist toward the target (`AimPose`), so the gun\'s\\nreal Muzzle points at it. One\\nJanitor per enemy record. PathfindingService:ComputeAsync is budgeted across\\nenemies so 40 enemies stay affordable. Deliberately simple: no cover, no\\ncoordination, no target leading.","realm":["Server"],"source":{"line":18,"path":"src/ServerStorage/SharedModules/EnemyBrain.luau"}}')}}]);